package io.github.turbopro.ism.qualification;
import io.github.turbopro.ism.common.infrastructure.tenant.TenantScopedMapper;
import org.apache.ibatis.annotations.*;
import java.util.List;
@Mapper public interface AdmissionResultMapper extends TenantScopedMapper {
 String COLUMNS="CAST(p.id AS CHAR) id,p.application_no,p.purchase_category,p.result,CASE WHEN c.kind='WITHDRAW' THEN '该结果已撤销发布，请联系邀请方确认。' ELSE COALESCE(c.public_comment,p.public_comment) END public_comment,p.published_at,CASE WHEN c.kind='WITHDRAW' THEN 'WITHDRAWN' ELSE 'ACTIVE' END publication_state,p.change_version publication_version,c.public_reason adjustment_reason,c.changed_at adjusted_at";
 String FROM=" FROM qua_admission_public_result p LEFT JOIN qua_admission_result_change c ON c.tenant_id=p.tenant_id AND c.publication_id=p.id AND c.change_no=p.change_version";
 @Select("SELECT application_id,supplier_id,change_version FROM qua_admission_public_result WHERE tenant_id=#{tenantId} AND id=#{publicationId} FOR UPDATE") AdmissionResultModels.Source lock(long tenantId,long publicationId);
 @Select("SELECT public_comment FROM qua_admission_public_result WHERE tenant_id=#{tenantId} AND application_id=#{id} AND source_version=#{version}") String originalByVersion(long tenantId,long id,int version);
 @Select("SELECT public_comment FROM qua_admission_public_result WHERE tenant_id=#{tenantId} AND application_id=#{id} AND id=#{publicationId}") String original(long tenantId,long id,long publicationId);
 @Select("SELECT change_no,kind,public_comment,public_reason FROM qua_admission_result_change WHERE tenant_id=#{tenantId} AND publication_id=#{publicationId} AND change_no=#{changeNo}") AdmissionResultModels.ChangeRow change(long tenantId,long publicationId,int changeNo);
 @Update("UPDATE qua_admission_public_result SET change_version=change_version+1 WHERE tenant_id=#{tenantId} AND id=#{publicationId} AND change_version=#{version}") int advance(long tenantId,long publicationId,int version);
 @Insert("INSERT INTO qua_admission_result_change(id,tenant_id,publication_id,change_no,kind,public_comment,public_reason,changed_by) VALUES(#{eventId},#{tenantId},#{publicationId},#{changeNo},#{kind},#{comment},#{reason},#{actor})") int insertChange(long eventId,long tenantId,long publicationId,int changeNo,String kind,String comment,String reason,long actor);
 @Select("SELECT "+COLUMNS+FROM+" WHERE p.tenant_id=#{tenantId} AND p.application_id=#{id} AND p.id=#{publicationId}") AdmissionResultModels.View find(long tenantId,long id,long publicationId);
 @Select("SELECT COUNT(*) FROM qua_admission_result_change WHERE tenant_id=#{tenantId} AND publication_id=#{publicationId}") long changeCount(long tenantId,long publicationId);
 @Select("SELECT change_no version,kind,public_comment,public_reason reason,changed_at FROM qua_admission_result_change WHERE tenant_id=#{tenantId} AND publication_id=#{publicationId} ORDER BY change_no DESC LIMIT #{size} OFFSET #{offset}") List<AdmissionResultModels.Change> changes(long tenantId,long publicationId,int offset,int size);

 @Select("SELECT r.id,r.action,r.to_status,r.application_version,(SELECT COUNT(*) FROM qua_admission_review x WHERE x.tenant_id=r.tenant_id AND x.application_id=r.application_id AND x.application_version IS NULL AND x.operated_at=r.operated_at) same_instant_count FROM qua_admission_review r WHERE r.tenant_id=#{tenantId} AND r.application_id=#{id} ORDER BY r.application_version DESC,r.operated_at DESC,r.id DESC LIMIT 1") AdmissionResultModels.Review latestReview(long tenantId,long id);
 @Select("SELECT "+COLUMNS+FROM+" WHERE p.tenant_id=#{tenantId} AND p.application_id=#{id} AND p.source_version=#{version}") AdmissionResultModels.View byVersion(long tenantId,long id,int version);
 @Select("SELECT "+COLUMNS+FROM+" WHERE p.tenant_id=#{tenantId} AND p.application_id=#{id} ORDER BY p.published_at DESC,p.source_version DESC,p.id DESC LIMIT 50") List<AdmissionResultModels.View> employeeList(long tenantId,long id);
 @Select("SELECT "+COLUMNS+FROM+" WHERE p.tenant_id=#{tenantId} AND p.supplier_id=#{supplierId} ORDER BY p.published_at DESC,p.source_version DESC,p.id DESC LIMIT #{size} OFFSET #{offset}") List<AdmissionResultModels.View> portalList(long tenantId,long supplierId,int offset,int size);
 @Select("SELECT COUNT(*) FROM qua_admission_public_result WHERE tenant_id=#{tenantId} AND supplier_id=#{supplierId}") long count(long tenantId,long supplierId);
 @Insert("INSERT INTO qua_admission_public_result(id,tenant_id,supplier_id,application_id,review_id,source_version,application_no,purchase_category,result,public_comment,published_by) VALUES(#{id},#{tenantId},#{supplierId},#{applicationId},#{review},#{version},#{number},#{category},#{result},#{comment},#{actor})") int publish(long id,long tenantId,long supplierId,long applicationId,long review,int version,String number,String category,String result,String comment,long actor);
}
